class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute, Market.USA)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option = option

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.current_slice = None
        self.expiration_processed_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnData(self, slice: Slice):
        self.current_slice = slice

        self.HandleUnexpectedSpyPosition()
        self.ProcessExpirationProtection()

        if self.held_option is not None and self.entry_price is not None:
            self.ProcessProfitTarget(slice)
            self.ProcessTimeStop()

        if self.entry_ticket is None or not self.IsOpen(self.entry_ticket):
            self.entry_ticket = None

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy:
            return

        local_end = bar.EndTime.astimezone(self.TimeZone).time()

        if local_end < time(9, 30) or local_end > time(16, 0):
            return

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = float(self.fast.Current.Value)
            self.previous_slow = float(self.slow.Current.Value)

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish_cross = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        eligible_time = time(9, 45) <= local_end <= time(14, 30)

        if bullish_cross and eligible_time:
            self.TryEnterCall()

    def TryEnterCall(self):
        if self.current_slice is None:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        chains = list(self.current_slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        minimum_expiration = today + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Symbol.ID.Date.date() >= minimum_expiration:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        expiration = min(
            contract.Symbol.ID.Date.date()
            for contract in contracts
        )

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Symbol.ID.Date.date() == expiration
            and contract.Symbol.ID.OptionStyle == OptionStyle.American
            and contract.Symbol.ID.OptionType == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )[0]

        self.held_option = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Call entry submitted: {} expiration {} strike {:.2f}".format(
                selected.Symbol,
                expiration,
                selected.Strike
            )
        )

    def ProcessProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        quote = self.GetOptionQuote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if midpoint < 1.50 * self.entry_price:
            return

        self.CancelOpenExitOrder()
        quantity = self.Portfolio[self.held_option].Quantity

        if quantity > 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity,
                tag="50% profit target"
            )
            self.Debug(
                "Profit-target exit submitted: {} midpoint {:.2f}".format(
                    self.held_option,
                    midpoint
                )
            )

    def ProcessTimeStop(self):
        if self.held_option is None:
            return

        expiration = self.held_option.ID.Date.date()
        if self.Time.date() != expiration - timedelta(days=1):
            return

        if self.Time.time() < time(15, 45):
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity > 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity,
                tag="expiration time stop"
            )
            self.Debug(
                "Expiration time-stop exit submitted: {}".format(
                    self.held_option
                )
            )

    def ProcessExpirationProtection(self):
        if self.held_option is None:
            return

        expiration = self.held_option.ID.Date.date()
        if self.Time.date() < expiration:
            return

        if self.expiration_processed_date == self.Time.date():
            return

        self.expiration_processed_date = self.Time.date()
        quantity = self.Portfolio[self.held_option].Quantity

        if quantity > 0:
            self.CancelOpenExitOrder()
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity,
                tag="expiration protection"
            )
            self.Debug(
                "Expiration protection exit submitted: {}".format(
                    self.held_option
                )
            )

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.MarketOrder(self.spy, -quantity, tag="unexpected exercise/assignment")
        self.Debug(
            "Unexpected SPY exercise/assignment position liquidated: {} shares".format(
                quantity
            )
        )

    def GetOptionQuote(self, slice: Slice, symbol: Symbol):
        security = self.Securities[symbol] if symbol in self.Securities else None
        if security is None:
            return None

        bid = security.BidPrice
        ask = security.AskPrice

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                break

        if bid <= 0 or ask <= 0:
            return None

        return bid, ask

    def CancelOpenExitOrder(self):
        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by higher-priority exit.")

    def IsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.FillQuantity > 0
            ):
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        self.entry_price
                    )
                )

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Call exit filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

        if order_event.Symbol.SecurityType == SecurityType.Equity:
